arguments.command:
# Check if there's a running instance on common ports
@(5000, 5001, 5002, 3000, 8080, 5224, 5225) | ForEach-Object {
    try { 
        $r = Invoke-WebRequest -Uri "http://localhost:$_/api" -UseBasicParsing -TimeoutSec 2
        "Port $_`: $($r.StatusCode) - $($r.Content.Substring(0, [Math]::Min(100, $r.Content.Length)))"
    } catch {
        if ($_.Exception.Message -notmatch "refused|timed out") { "Port $_`: $($_.Exception.Message)" }
    }
}

