} | ConvertTo-Json
$enlist = Invoke-WebRequest -Uri "http://localhost:5256/api/squads/enlist" -Method POST -Body $body -ContentType "application/json" -UseBasicParsing -TimeoutSec 10
$enlist.Content","description":"Enlist the Compliance Auditors squad"}

